import {createClient} from '@supabase/supabase-js';
import {icon} from './icons.js';
import {money,number,escape as e,estimate,filterOffers,hasLatamProjection,airlineLabel,origins,destinations,defaultSettings,demoOffers,addDays} from './domain.js';

const configured=Boolean(__SUPABASE_URL__&&__SUPABASE_KEY__);
const db=configured?createClient(__SUPABASE_URL__,__SUPABASE_KEY__,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}}):null;
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
let demo=new URLSearchParams(location.search).get('demo')==='1';
let session=null,profile=null,offers=[],favorites=[],monitors=[],runs=[],members=[],calendarJobs=[],settings=structuredClone(defaultSettings);
let page='discover',region='all',origin='all',search='',sort='best',maxPrice='',departureFrom='',departureTo='',authMode='login',busy=false;
let prefs={cost_per_thousand:20,estimated_taxes:350};
let timer;
const titles={discover:'Explorar oportunidades',saved:'Minhas favoritas',radars:'Meus radares',activity:'Atividade do motor',settings:'Preferências',plans:'Meu plano',admin:'Administração'};
const fmtDate=(s,year=false)=>new Date(`${s}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',...(year?{year:'numeric'}:{})}).replace('.','');
const initial=()=>e((profile?.full_name||'Viajante').trim().split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase());
const isAdmin=()=>demo||profile?.role==='admin';
const isPro=()=>demo||profile?.plan==='pro'&&(!profile.pro_until||new Date(profile.pro_until)>new Date());
function toast(message){clearTimeout(timer);document.querySelector('#toast').innerText=message;document.querySelector('#toast').classList.add('show');timer=setTimeout(()=>document.querySelector('#toast').classList.remove('show'),4400);}
function fail(err){console.error(err?.message||'Falha');toast(err?.message||'Não foi possível concluir. Tente novamente.');}
function check(result){if(result.error)throw result.error;return result.data;}
function logo(){return `<a class="brand" href="#discover" aria-label="Órbita, início"><img src="./favicon.svg" alt="" width="34" height="34"><span>órbita<span class="brand-dot">.</span></span></a>`;}
function globeArt(){return `<svg class="hero-globe" viewBox="0 0 500 280" fill="none" aria-hidden="true"><defs><radialGradient id="orb"><stop stop-color="#a68cf6" stop-opacity=".6"/><stop offset="1" stop-color="#7655dc" stop-opacity="0"/></radialGradient></defs><circle cx="280" cy="145" r="150" fill="url(#orb)"/><g stroke="#c0a8ff" stroke-opacity=".36"><circle cx="280" cy="145" r="108"/><ellipse cx="280" cy="145" rx="50" ry="108"/><ellipse cx="280" cy="145" rx="87" ry="108"/><ellipse cx="280" cy="145" rx="108" ry="40"/><ellipse cx="280" cy="145" rx="108" ry="77"/><path d="M172 145h216M280 37v216"/></g><path d="m202 81 24-11 28 8 7 17-13 10-11 21-20-3-10-23Zm35 51 16 2 20 25-4 30-17 30-9-24 3-30-14-15Zm62-47 15-13 40 5 20 20-13 14-27-1-11 21-23-6-7-19Zm3 44 27 5 9 23-12 29-19-9-13-29Z" fill="#b49bf7" opacity=".38"/><ellipse cx="280" cy="145" rx="165" ry="55" stroke="#d3c2ff" stroke-dasharray="4 6" transform="rotate(-30 280 145)" opacity=".7"/><g transform="translate(405 62) rotate(25)"><path d="m0-15 4 10 14 8v4L4 3l-1 10H0l-3-10-14 4V3l13-8Z" fill="#d8fd9b"/></g><circle cx="186" cy="181" r="5" fill="#d8fd9b"/><circle cx="186" cy="181" r="11" stroke="#d8fd9b" stroke-opacity=".3"/><circle cx="331" cy="92" r="4" fill="#fff"/></svg>`;}
function cityArt(o){const id=o.destination;const beach=['MIA','MCO','LAX'].includes(id);const paris=id==='CDG';const lisbon=['LIS','MAD','BCN'].includes(id);return `<svg class="city-art" viewBox="0 0 600 190" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky-${e(id)}" x2="1" y2="1"><stop stop-color="${beach?'#d3e9ec':paris?'#e4dce9':lisbon?'#f5dfcd':'#dfe4ef'}"/><stop offset="1" stop-color="${beach?'#f4e2d4':paris?'#f2e3da':lisbon?'#ebd6ce':'#c5cde1'}"/></linearGradient></defs><path fill="url(#sky-${e(id)})" d="M0 0h600v190H0z"/><circle cx="${beach?450:120}" cy="52" r="26" fill="#fff7e9" opacity=".8"/><path d="M0 151q110-28 220 0t220 0 160 0v39H0Z" fill="${beach?'#8bc1c1':'#c9bac5'}" opacity=".5"/>${beach?'<path d="M0 158h600v32H0Z" fill="#93bfc3"/><path d="M0 174q150-10 300 2t300-1" stroke="#e9f5ed" fill="none"/><g fill="#dfc6be"><path d="M150 151V95h50v56m20 0V78h47v73m15 0V108h48v43m20 0V60h45v91"/></g><g stroke="#576e65" stroke-width="5" fill="none"><path d="M86 167q14-44 0-88m0 0q-35-23-58 4m58-4q24-28 47-8m-47 8q-5-35-25-34m25 34q27-7 37 14m-37-14q-31 0-38 24"/></g>':paris?'<g fill="#9c8c9e"><path d="m300 25-8 70-33 67h18l23-44 23 44h18l-33-67Zm-18 107h36v7h-36Zm8-38h20v5h-20Z"/><path d="M45 164v-52h62v52m12 0v-35h46v35m15 0v-54h61v54m120 0v-45h56v45m15 0v-65h73v65m14 0v-43h45v43"/></g>':lisbon?'<g fill="#b99794"><path d="M50 158v-54l28-16 28 16v54m8 0V81l32-18 31 18v77m8 0V99h56v59m8 0V75l32-20 32 20v83m12 0V96h54v62m8 0v-41h57v41m7 0V80l34-18 34 18v78"/></g><g fill="#f8e4bc"><path d="M80 137h6v9h-6m50-48h7v11h-7m25 0h7v11h-7m105-15h7v11h-7m23 10h7v11h-7m177-34h7v11h-7"/></g><rect x="347" y="131" width="63" height="29" rx="4" fill="#d7b161"/><path d="M353 135h49v12h-49" fill="#e9dec5"/>':'<g fill="#8592ac"><path d="M45 164v-58h40v58m10 0V75h38v89m12 0V91h43v73m12 0V53h32v111m13 0V80h39v84m14 0V44h42v120m12 0V60h38v104m13 0V35h38v129m14 0V72h50v92m14 0V93h40v71"/></g><path d="M219 53V29m139 31V38m56-3V12" stroke="#8592ac" stroke-width="3"/><g stroke="#c5d1df" stroke-width="3" stroke-dasharray="4 7"><path d="M110 85v65m106-87v87m97-94v95m101-104v108m63-73v67"/></g>'}<path d="M0 164h600" stroke="#fff" stroke-opacity=".4"/></svg>`;}

function authView(){root.innerHTML=`<main class="auth-layout"><section class="auth-story">${logo()}<span class="eyebrow light">MENOS MILHAS. MAIS MUNDO.</span><h1>O mundo é grande.<br>O preço da sua passagem<br>não precisa ser.</h1><p>Encontre oportunidades internacionais saindo do Brasil e planeje sua próxima viagem com mais inteligência.</p>${globeArt()}<div class="story-bottom"><span>${icon('radar')} Um novo olhar para as tarifas, a cada 4 horas</span><small>Independente. Sem vínculo com LATAM ou Google.</small></div></section><section class="auth-panel"><div class="auth-box"><span class="mini-label">SEU PRÓXIMO DESTINO COMEÇA AQUI</span><h2>${authMode==='signup'?'Entre em uma nova órbita.':authMode==='reset'?'Vamos recuperar seu acesso.':authMode==='recovery'?'Uma nova senha.':'Bom ter você por aqui.'}</h2><p class="muted">${authMode==='signup'?'Crie sua conta gratuita e comece a explorar.':authMode==='reset'?'Enviaremos um link para o seu e-mail.':authMode==='recovery'?'Escolha uma senha de pelo menos 10 caracteres.':'Acesse seu radar de oportunidades internacionais.'}</p>${['login','signup'].includes(authMode)?`<div class="segmented auth-tabs"><button data-auth="login" class="${authMode==='login'?'selected':''}">Entrar</button><button data-auth="signup" class="${authMode==='signup'?'selected':''}">Criar conta</button></div>`:''}<form id="auth-form">${authMode==='signup'?'<label>Seu nome<input name="name" autocomplete="name" maxlength="100" required placeholder="Como podemos chamar você?"></label>':''}${authMode!=='recovery'?'<label>E-mail<input name="email" type="email" autocomplete="email" required placeholder="voce@exemplo.com"></label>':''}${authMode!=='reset'?`<label>Senha<input name="password" type="password" autocomplete="${authMode==='login'?'current-password':'new-password'}" minlength="${authMode==='login'?1:10}" required placeholder="${authMode==='login'?'Sua senha':'Pelo menos 10 caracteres'}"></label>`:''}${authMode==='signup'?'<label class="checkbox-row"><input name="consent" type="checkbox" required> Concordo com os termos de uso e a política de privacidade.</label><button type="button" class="text-button legal-link" data-legal>Consultar termos e privacidade</button>':''}<button class="button primary wide" type="submit">${authMode==='signup'?'Criar minha conta':authMode==='reset'?'Enviar link':authMode==='recovery'?'Salvar nova senha':'Entrar na minha conta'} ${icon('arrow')}</button><p class="form-message" id="auth-message" role="status"></p></form><button class="text-button" data-auth="${authMode==='login'?'reset':'login'}">${authMode==='login'?'Esqueci minha senha':'Voltar para entrar'}</button><div class="auth-divider"><span>CONHEÇA ANTES DE EMBARCAR</span></div><button class="button secondary wide" id="enter-demo">Explorar demonstração ${icon('external')}</button><p class="auth-note">Demonstração com dados fictícios. ${configured?'Seus dados reais são protegidos por login.':'A integração de produção ainda precisa ser configurada.'}</p><div class="auth-security">${icon('shield')} Acesso protegido com Supabase Auth</div></div></section></main>`;
document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;authView();});
document.querySelector('#enter-demo').onclick=()=>{demo=true;history.replaceState(null,'','?demo=1');loadDemo();};
document.querySelector('[data-legal]')?.addEventListener('click',legalView);
document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const f=new FormData(event.target);try{if(!db)throw new Error('O cadastro real será liberado após conectar o projeto Supabase. Você já pode explorar a demonstração.');const email=f.get('email'),password=f.get('password');if(authMode==='signup'){const {data,error}=await db.auth.signUp({email,password,options:{data:{full_name:f.get('name'),terms_accepted_at:new Date().toISOString(),terms_version:'2026-10-17'},emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session){session=data.session;await loadLive();}else document.querySelector('#auth-message').innerText='Confira seu e-mail para confirmar o cadastro. Se já possui conta, entre com sua senha.';}else if(authMode==='reset'){check(await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname}));document.querySelector('#auth-message').innerText='Se houver uma conta para este e-mail, você receberá o link de recuperação.';}else if(authMode==='recovery'){check(await db.auth.updateUser({password}));toast('Senha atualizada.');await loadLive();}else{const data=check(await db.auth.signInWithPassword({email,password}));session=data.session;await loadLive();}}catch(err){document.querySelector('#auth-message').innerText=err.message;}finally{button.disabled=false;}};}

function loadDemo(){profile={full_name:'Felipe Teixeira',email:'viajante@demonstracao.local',plan:'pro',role:'admin',status:'active'};offers=structuredClone(demoOffers);favorites=JSON.parse(localStorage.getItem('orbita-demo-favorites')||'[]');monitors=JSON.parse(localStorage.getItem('orbita-demo-monitors')||'null')||[{id:'m1',origin:'FLN',destination:'MIA',min_days:7,max_days:20,target_price:3500,enabled:true},{id:'m2',origin:'CWB',destination:'LIS',min_days:10,max_days:16,target_price:4200,enabled:true}];settings=JSON.parse(localStorage.getItem('orbita-demo-settings')||'null')||structuredClone(defaultSettings);settings.origins=settings.origins.filter(c=>origins.some(([code])=>code===c));monitors=monitors.filter(m=>origins.some(([code])=>code===m.origin));runs=[];members=[];calendarJobs=[];render();}
async function loadLive(){try{const p=check(await db.from('profiles').select('*').eq('id',session.user.id).single());profile=p;if(p.status!=='active'){await db.auth.signOut();session=null;profile=null;authView();toast('Seu acesso está suspenso. Contate a administração.');return;}const r=await Promise.allSettled([db.from('offers').select('*').gt('expires_at',new Date().toISOString()).gte('departure_date',new Date().toLocaleDateString('en-CA')).order('price_brl').limit(1000),db.from('favorites').select('offer_id'),db.from('monitors').select('*').order('created_at'),db.from('scan_runs').select('*').order('started_at',{ascending:false}).limit(20),db.from('preferences').select('*').maybeSingle(),db.from('scanner_settings').select('*').eq('id',1).single(),...(p.role==='admin'?[db.from('profiles').select('*').order('created_at',{ascending:false}).limit(200),db.from('calendar_jobs').select('id,status,request,result,error,created_at,expires_at').order('created_at',{ascending:false}).limit(8)]:[])]);const values=r.map(x=>{if(x.status==='rejected')throw x.reason;return check(x.value);});offers=values[0]||[];favorites=(values[1]||[]).map(f=>f.offer_id);monitors=values[2]||[];runs=values[3]||[];prefs=values[4]||prefs;settings=values[5]||settings;members=values[6]||[];calendarJobs=values[7]||[];render();}catch(err){root.innerHTML=`<main class="failure">${logo()}<h1>Não conseguimos carregar seu radar.</h1><p>${e(err.message)}</p><button class="button primary" id="retry">Tentar novamente</button><button class="button secondary" id="exit">Sair</button></main>`;document.querySelector('#retry').onclick=loadLive;document.querySelector('#exit').onclick=logout;}}
function navItem(key,ico,label){return `<button data-page="${key}" class="nav-item ${page===key?'active':''}">${icon(ico)}<span>${label}</span>${key==='saved'&&favorites.length?`<b>${favorites.length}</b>`:''}</button>`;}
function render(){if(!profile)return authView();root.innerHTML=`<div class="app-layout"><aside class="sidebar">${logo()}<div class="workspace-label">SEU UNIVERSO DE VIAGENS</div><nav aria-label="Navegação principal">${navItem('discover','grid','Explorar oportunidades')}${navItem('radars','radar','Meus radares')}${navItem('saved','heart','Minhas favoritas')}${navItem('activity','chart','Atividade do motor')}<div class="nav-divider"></div>${navItem('settings','settings','Preferências')}${navItem('plans','sparkle','Meu plano')}${isAdmin()?navItem('admin','users','Administração'):''}</nav><div class="sidebar-bottom"><div class="upgrade-card"><span>${icon('sparkle')} UM MUNDO DE POSSIBILIDADES</span><h3>Viajar mais.<br>Gastar melhor.</h3><p>Conheça o que está chegando ao Órbita Pro.</p><button data-page="plans">Descobrir o Pro ${icon('arrow')}</button></div><button class="account-nav" data-page="settings"><span class="avatar">${initial()}</span><span><strong>${e(profile.full_name?.split(' ')[0]||'Viajante')}</strong><small>${demo?'Conta de demonstração':isPro()?'Órbita Pro':'Órbita Free'}</small></span>${icon('down')}</button><button class="logout" id="logout">${icon('logout')} ${demo?'Sair da demonstração':'Sair da conta'}</button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Abrir navegação">${icon('menu')}</button><span>Meu espaço</span>${icon('chevron')}<strong>${titles[page]}</strong></div><div class="top-actions"><span class="secure-label">${icon('lock')} Área privada</span><button class="icon-button" data-page="activity" aria-label="Ver atividade das pesquisas">${icon('bell')}</button><span class="avatar small">${initial()}</span></div></header>${demo?'<div class="demo-bar"><span><b>Modo demonstração</b> · Tarifas e projeções fictícias para explorar a plataforma.</span><button id="demo-signup">Criar minha conta '+icon('arrow')+'</button></div>':''}<main id="content" tabindex="-1">${pageContent()}</main><footer>Órbita <span>·</span> Mais possibilidades em cada viagem.<div>Projeto independente de LATAM Pass e Google Flights. <button class="text-button" data-legal>Termos e privacidade</button></div></footer></div></div>`;bindShell();bindPage();}
function pageContent(){switch(page){case'discover':case'saved':return discoverView();case'radars':return radarView();case'activity':return activityView();case'settings':return settingsView();case'plans':return plansView();case'admin':return isAdmin()?adminView():'';}}
function bindShell(){document.querySelectorAll('.brand').forEach(b=>b.onclick=ev=>{ev.preventDefault();page='discover';render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0);});document.querySelector('#logout').onclick=logout;document.querySelector('#demo-signup')?.addEventListener('click',()=>{demo=false;profile=null;history.replaceState(null,'',location.pathname);authMode='signup';authView();});document.querySelector('.mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.querySelector('[data-legal]')?.addEventListener('click',legalView);}
async function logout(){if(db&&!demo)await db.auth.signOut();session=null;profile=null;demo=false;page='discover';history.replaceState(null,'',location.pathname);authView();}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function discoverView(){const saved=page==='saved';const valid=offers.filter(o=>origins.some(([code])=>code===o.origin)&&new Date(o.expires_at)>new Date());const list=filterOffers(saved?valid.filter(o=>favorites.includes(o.id)):valid,{region,origin,search,maxPrice,departureFrom,departureTo});list.sort((a,b)=>sort==='recent'?new Date(b.collected_at)-new Date(a.collected_at):a.price_brl-b.price_brl);const best=valid.length?Math.min(...valid.map(o=>o.price_brl)):0;return `${saved?heading('PARA TIRAR DO PAPEL','Seus próximos destinos.','As oportunidades que você guardou para olhar com calma.'):`<div class="greeting"><span>${icon('sparkle')} A próxima boa viagem está no seu radar.</span><small>${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</small></div><section class="hero"><div class="hero-copy"><span class="eyebrow light">SEU PASSAPORTE PARA NOVAS POSSIBILIDADES</span><h1>Seu próximo destino.<br><span>Por muito menos.</span></h1><p>Tarifas de várias companhias e uma nova perspectiva<br class="desktop"> para planejar sua viagem com milhas.</p><button class="button hero-button" id="hero-radar">${icon('plus')} Criar meu radar ${icon('arrow')}</button></div>${globeArt()}<div class="hero-caption"><span class="status-dot"></span> DO BRASIL PARA O MUNDO</div></section><div class="stats-grid"><article class="stat"><span class="stat-icon lilac">${icon('plane')}</span><div><small>Oportunidades no radar</small><strong>${String(valid.length).padStart(2,'0')} <em>ida e volta</em></strong></div></article><article class="stat"><span class="stat-icon mint">${icon('wallet')}</span><div><small>Menor tarifa encontrada</small><strong>${best?money(best):'—'} <em>por pessoa</em></strong></div></article><article class="stat"><span class="stat-icon peach">${icon('trend')}</span><div><small>Meta para ofertas LATAM</small><strong>25–30% <em>simulação*</em></strong></div></article></div>`}<section class="opportunities"><div class="section-heading"><div><h2>${saved?'Favoritas para sua próxima viagem':'Um mundo de oportunidades'} <span class="count-tag">${list.length}</span></h2><p>${saved?'Todas as suas favoritas, em um só lugar.':'Encontre a viagem que combina com os seus planos.'}</p></div><button class="button secondary compact" id="open-filters">${icon('settings')} Filtros ${departureFrom||departureTo||maxPrice?'<span class="filter-dot"></span>':''}</button></div><div class="filter-row"><div class="region-tabs" role="group" aria-label="Filtrar por região">${[['all','Todos os destinos'],['EUA','Estados Unidos'],['Europa','Europa'],['Ásia','Ásia']].map(([v,l])=>`<button class="${region===v?'selected':''}" data-region="${v}">${v==='all'?icon('globe'):''}${l}</button>`).join('')}</div><div class="search-input">${icon('search')}<input id="search" aria-label="Buscar destino" placeholder="Qual o seu próximo destino?" value="${e(search)}"></div></div><div class="results-toolbar"><label>Saindo de <select id="origin-filter" aria-label="Filtrar origem"><option value="all">Todos os aeroportos</option>${origins.map(([c,n])=>`<option value="${c}" ${origin===c?'selected':''}>${n} (${c})</option>`).join('')}</select></label><label>Ordenar por <select id="sort" aria-label="Ordenar oportunidades"><option value="best" ${sort==='best'?'selected':''}>Menor tarifa</option><option value="recent" ${sort==='recent'?'selected':''}>Mais recentes</option></select></label></div><div class="offers-grid">${list.length?list.map(card).join(''):emptyState(saved?'heart':'search',saved?'Seu próximo sonho fica aqui.':'Novos horizontes, em breve.',saved?'Toque no coração de uma oportunidade para guardá-la.':region==='Ásia'?'Ative os destinos asiáticos na Administração ou crie um radar personalizado.':demo?'Nenhuma oportunidade para esses filtros. Tente outra origem ou destino.':'As tarifas aparecerão após a primeira pesquisa real. Acompanhe o motor na área de atividade.')}</div><div class="estimate-note">${icon('info')}<p><b>*Uma projeção para planejar melhor.</b> Nas ofertas identificadas como LATAM, a faixa de 25–30% é uma meta de economia, não uma oferta de resgate. A quantidade de milhas, as taxas e a disponibilidade precisam ser verificadas no LATAM Pass. Tarifas em reais podem mudar.</p></div></section>`;}
function card(o){
 const est=estimate(o.price_brl,prefs.cost_per_thousand,prefs.estimated_taxes),latam=hasLatamProjection(o);
 const target=monitors.some(m=>m.enabled&&m.origin===o.origin&&m.destination===o.destination&&m.target_price&&o.price_brl<=m.target_price&&o.stay_days>=m.min_days&&o.stay_days<=m.max_days);
 return `<article class="offer-card"><div class="card-image">${cityArt(o)}<span class="image-tag">${target?'DENTRO DA SUA META':o.is_demo?'EXEMPLO ILUSTRATIVO':'TARIFA CONSULTADA'}</span><button class="favorite ${favorites.includes(o.id)?'saved':''}" data-favorite="${e(o.id)}" aria-label="${favorites.includes(o.id)?'Remover':'Salvar'} ${e(o.city)}" aria-pressed="${favorites.includes(o.id)}">${icon('heart')}</button><div class="city-title"><span>${e(o.country)}</span><h3>${e(o.city)}</h3></div></div><div class="card-body"><div class="carrier-line"><span class="${latam?'latam-mark':'airline-mark'}">${latam?'▰':icon('plane')}</span><b>${e(airlineLabel(o))}</b></div><div class="route-line"><span>${e(o.origin)} ${icon('arrow')} ${e(o.destination)}</span><small>${o.stops===0?'Direto':o.stops===1?'1 conexão':`${o.stops} conexões`}</small></div><div class="travel-dates">${icon('calendar')}<span>${fmtDate(o.departure_date)} — ${fmtDate(o.return_date)}</span><b>${o.stay_days} dias</b></div><div class="cash-price"><div><span>Ida e volta · econômica</span><strong>${money(o.price_brl)}</strong></div><span class="price-note">por pessoa<br>em dinheiro</span></div>${latam?`<div class="miles-projection"><div><span>${icon('sparkle')} Projeção LATAM*</span><b>${money(est.low)} <span>a</span> ${money(est.high)}</b></div><span class="projection-badge">25–30%<small>meta de economia</small></span></div>`:`<div class="cash-only"><span>${icon('plane')} Tarifa em reais</span><small>Compare datas e condições no Google Flights.</small></div>`}<button class="card-action" data-detail="${e(o.id)}">Explorar oportunidade ${icon('arrow')}</button></div></article>`;
}

function emptyState(ico,title,text){return `<div class="empty-state">${icon(ico)}<h3>${title}</h3><p>${text}</p></div>`;}
function radarView(){return `${heading('SEMPRE DE OLHO NO SEU PRÓXIMO DESTINO','Seus planos, no radar.','Personalize rotas, datas e o valor que faz sentido para você.',`<button class="button primary" id="new-radar">${icon('plus')} Novo radar</button>`)}<div class="info-strip">${icon('clock')} O motor consulta o Google Flights a cada 4 horas. Seus radares entram na fila de pesquisa com o intervalo escolhido.</div><div class="panel"><div class="panel-heading"><h2>Rotas monitoradas <span class="count-tag">${monitors.length}</span></h2><span class="muted">${isPro()?'Até 30 radares no Pro':'Até 3 radares no Free'}</span></div>${monitors.length?`<div class="table-scroll"><table><thead><tr><th>Rota</th><th>Permanência</th><th>Tarifa desejada</th><th>Status</th><th></th></tr></thead><tbody>${monitors.map(m=>`<tr><td><div class="table-route"><span class="route-icon">${icon('plane')}</span><div><b>${e(m.origin)} ${icon('arrow')} ${e(m.destination)}</b><small>${e(destinations.find(d=>d.code===m.destination)?.city||m.destination)}</small></div></div></td><td>${m.min_days} a ${m.max_days} dias</td><td>${m.target_price?money(m.target_price):'Sem limite'}</td><td><span class="status-pill ${m.enabled?'green':'neutral'}">${m.enabled?'Monitorando':'Pausado'}</span></td><td class="row-actions"><button class="text-button" data-toggle-monitor="${e(m.id)}">${m.enabled?'Pausar':'Ativar'}</button><button class="icon-button" data-delete-monitor="${e(m.id)}" aria-label="Excluir radar ${e(m.destination)}">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('radar','Deixe o radar trabalhar por você.','Adicione sua primeira rota para acompanhar novas oportunidades.')}</div><div class="two-columns"><div class="insight-card">${icon('globe')}<h3>Seis meses de possibilidades.</h3><p>As pesquisas começam com saídas de amanhã e percorrem os próximos seis meses. A volta pode ocorrer depois desse horizonte.</p></div><div class="insight-card">${icon('bell')}<h3>Seus alvos, em destaque.</h3><p>O valor desejado ajuda a destacar oportunidades na plataforma. Alertas por e-mail serão uma evolução futura.</p></div></div>`;}
function activityView(){const latest=runs[0];return `${heading('TRANSPARÊNCIA EM CADA CONSULTA','O radar nos bastidores.','Descoberta por calendário e confirmação de tarifas, contadas separadamente.')}<div class="stats-grid"><article class="stat"><span class="stat-icon lilac">${icon('clock')}</span><div><small>Frequência programada</small><strong>4 horas</strong></div></article><article class="stat"><span class="stat-icon mint">${icon('calendar')}</span><div><small>Preços no calendário · última rodada</small><strong>${latest?number(latest.calendar_entries||0):'—'}</strong></div></article><article class="stat"><span class="stat-icon peach">${icon('search')}</span><div><small>Consultas detalhadas · última rodada</small><strong>${latest?number(latest.detail_queries??latest.queries_attempted):'—'}</strong></div></article></div>${latest?`<div class="info-strip">${icon('info')}<div><b>${({available:'Calendário disponível',unavailable:'Calendário indisponível · busca detalhada utilizada',pending:'Verificando calendário',partial:'Calendário parcial · preços reais capturados',disabled:'Busca detalhada'})[latest.calendar_status||'disabled']}</b><p>${e(latest.message||'')} Matriz configurada: ${number(latest.total_combinations)} combinações de rota e datas.</p></div></div>`:''}<div class="panel"><div class="panel-heading"><h2>Histórico das pesquisas</h2><span class="status-pill neutral">${latest?'Execuções reais':'Sem execução real'}</span></div>${runs.length?`<div class="table-scroll"><table><thead><tr><th>Início</th><th>Status</th><th>Calendários / preços</th><th>Detalhadas</th><th>Tarifas</th><th>Falhas</th></tr></thead><tbody>${runs.map(r=>`<tr><td>${new Date(r.started_at).toLocaleString('pt-BR')}</td><td><span class="status-pill ${r.status==='completed'?'green':'neutral'}">${e({completed:'Concluída',partial:'Parcial',failed:'Falhou',running:'Em andamento'}[r.status]||r.status)}</span></td><td>${number(r.calendar_queries||0)} / ${number(r.calendar_entries||0)}</td><td>${number(r.detail_queries??r.queries_attempted)}</td><td>${number(r.offers_found)}</td><td>${number(r.errors_count)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('clock','Aguardando o primeiro sinal.',demo?'A demonstração não executa consultas nem simula execuções concluídas.':'As execuções do motor aparecerão aqui automaticamente.')}</div><div class="info-strip">${icon('info')} Preços do calendário servem para escolher datas. Só a consulta detalhada publica uma oferta com companhia identificada. A rodada consulta parte da matriz e retoma a fila nas próximas execuções.</div>`;}

function settingsView(){return `${heading('DO SEU JEITO','Ajuste sua órbita.','Suas premissas de milhas e preferências de acesso.')}<form id="preferences-form" class="panel form-panel"><div class="panel-heading"><div><h2>Simulador de milhas</h2><p>Use o seu custo real de aquisição para planejar.</p></div><span class="pill">Somente estimativas</span></div><div class="form-grid"><label>Custo por 1.000 milhas (R$)<input type="number" name="cost_per_thousand" min="1" max="200" step="0.01" value="${prefs.cost_per_thousand}" required><small>Quanto você paga, em média, por mil milhas.</small></label><label>Taxas estimadas por ida e volta (R$)<input type="number" name="estimated_taxes" min="0" max="10000" step="1" value="${prefs.estimated_taxes}" required><small>Valor ilustrativo. As taxas reais variam por viagem.</small></label></div><div class="form-footer"><p>A meta de economia é de 25% a 30% sobre a tarifa em reais.</p><button class="button primary" type="submit">Salvar preferências ${icon('check')}</button></div></form><div class="panel form-panel"><div class="panel-heading"><h2>Sua conta</h2><span class="status-pill green">${demo?'Demonstração':'Ativa'}</span></div><div class="form-grid"><div><span class="field-label">Nome</span><p>${e(profile.full_name||'Viajante')}</p></div><div><span class="field-label">E-mail</span><p>${e(profile.email)}</p></div></div><button class="text-button" id="change-password">Alterar minha senha</button></div><div class="panel form-panel"><div class="panel-heading"><h2>Aeroportos e destinos</h2></div><p class="muted">Personalize as suas rotas em <button class="text-button" data-go-radars>Meus radares</button>. ${isAdmin()?'A lista global e o intervalo padrão são configurados na Administração.':''}</p><div class="airport-list">${origins.map(([c,n,s])=>`<span><b>${c}</b> ${n} <small>${s}</small></span>`).join('')}</div></div>`;}
function plansView(){return `${heading('PARA CADA JEITO DE VIAJAR','Escolha seu próximo passo.','Comece a explorar agora. Amplie suas possibilidades quando o Pro chegar.')}<div class="plans-grid"><article class="plan-card"><span class="eyebrow">ÓRBITA FREE</span><h2>O primeiro embarque.</h2><p>Para começar a acompanhar oportunidades.</p><strong class="plan-price">Grátis</strong><span>Seu ponto de partida</span><ul><li>${icon('check')} Acesso às tarifas disponíveis</li><li>${icon('check')} Até 3 radares personalizados</li><li>${icon('check')} Favoritos e projeção de milhas</li><li>${icon('check')} Pesquisas compartilhadas a cada 4 horas</li></ul><button class="button secondary wide" disabled>${isPro()?'Plano gratuito disponível':'Seu plano atual'}</button></article><article class="plan-card featured"><span class="plan-ribbon">EM BREVE</span><span class="eyebrow">ÓRBITA PRO</span><h2>Mais mundo no radar.</h2><p>Para quem está sempre planejando a próxima.</p><strong class="plan-price">Mais possibilidades.</strong><span>Preço e lançamento a definir</span><ul><li>${icon('check')} Até 30 radares personalizados</li><li>${icon('check')} Tudo o que existe no Free</li><li>${icon('check')} Base preparada para assinatura</li><li>${icon('check')} Novos recursos serão anunciados no lançamento</li></ul><button class="button primary wide" id="pro-interest">${icon('sparkle')} Quero saber quando lançar ${icon('arrow')}</button></article></div><p class="center muted">Nenhuma cobrança será feita. O Pro ainda não está à venda.</p>`;}
function adminView(){return `${heading('CENTRAL DE CONTROLE','Tudo na mesma órbita.','Gerencie o motor e os acessos da plataforma.')}<form id="scanner-form" class="panel form-panel"><div class="panel-heading"><div><h2>Motor de pesquisa</h2><p>Google Flights · várias companhias · BRL · 1 adulto</p></div><label class="switch-label"><input type="checkbox" name="enabled" ${settings.enabled?'checked':''}> Motor habilitado</label></div><div class="form-grid three"><label>Permanência mínima (dias)<input name="min_days" type="number" min="1" max="60" required value="${settings.min_days}"></label><label>Permanência máxima (dias)<input name="max_days" type="number" min="1" max="60" required value="${settings.max_days}"></label><label>Horizonte de saída<select name="horizon_months">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${settings.horizon_months===n?'selected':''}>Próximos ${n} ${n===1?'mês':'meses'}</option>`).join('')}</select></label><label>Estratégia<select name="search_strategy"><option value="hybrid" ${settings.search_strategy!=='detailed'?'selected':''}>Calendário + validação detalhada</option><option value="detailed" ${settings.search_strategy==='detailed'?'selected':''}>Somente busca detalhada</option></select></label><label>Modo de pesquisa<select name="search_mode"><option value="rolling" ${settings.search_mode==='rolling'?'selected':''}>Contínua · retoma a fila</option><option value="exhaustive" ${settings.search_mode==='exhaustive'?'selected':''}>Ampliada · até 3 horas</option></select></label><label>Consultas por rodada contínua<input name="query_budget" type="number" min="1" max="100000" required value="${settings.query_budget}"></label><label>Máximo de conexões<select name="max_stops">${[0,1,2].map(n=>`<option value="${n}" ${settings.max_stops===n?'selected':''}>${n===0?'Somente diretos':n+' conexões'}</option>`).join('')}</select></label></div><h3 class="form-section-title">Aeroportos de origem</h3><div class="checkbox-grid">${origins.map(([c,n,s])=>`<label><input type="checkbox" name="origins" value="${c}" ${settings.origins.includes(c)?'checked':''}><span><b>${c}</b> ${n}<small>${s}</small></span></label>`).join('')}</div><h3 class="form-section-title">Destinos internacionais</h3><p class="muted small-copy">Os destinos asiáticos podem ser ativados para buscar qualquer companhia. A inclusão não confirma operação da rota.</p><div class="checkbox-grid">${settings.destinations.map(d=>`<label><input type="checkbox" name="destinations" value="${e(d.code)}" ${d.enabled?'checked':''}><span><b>${e(d.code)}</b> ${e(d.city)}<small>${e(d.region)}</small></span></label>`).join('')}</div><button type="button" class="text-button" id="add-destination">${icon('plus')} Adicionar destino</button><div class="info-strip">${icon('info')} O orçamento inclui calendário e consultas detalhadas. Se o calendário estiver indisponível, o motor usa a busca detalhada. A varredura completa pode exceder as 4 horas entre rodadas. O GitHub Actions pode atrasar execuções.</div><div class="form-footer"><p>Alterações valem a partir da próxima rodada.</p><button type="submit" class="button primary">Salvar configuração ${icon('check')}</button></div></form>${calendarAdminView()}<div class="panel"><div class="panel-heading"><h2>Usuários e acessos</h2><span class="count-tag">${members.length}</span></div>${members.length?`<div class="table-scroll"><table><thead><tr><th>Usuário</th><th>Plano</th><th>Acesso</th><th></th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${e(m.full_name)}</b><small class="block">${e(m.email)}</small></td><td>${e(m.plan)} ${m.role==='admin'?'· Admin':''}</td><td><span class="status-pill ${m.status==='active'?'green':'neutral'}">${m.status==='active'?'Ativo':'Suspenso'}</span></td><td><button class="text-button" data-member="${e(m.id)}">Gerenciar ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('users','Pronto para receber novos viajantes.',demo?'Usuários reais serão exibidos após conectar o Supabase.':'Os cadastros aparecerão aqui automaticamente.')}</div>`;}

function calendarAdminView(){return `<section class="panel form-panel"><div class="panel-heading"><div><h2>Calendário próprio</h2><p>Capture preços do Google Flights para sua rota e intervalo.</p></div><span class="pill">API autenticada</span></div><form id="calendar-form"><div class="form-grid three"><label>Origem da captura<select name="origin">${origins.map(([code,name])=>`<option value="${code}" ${code==='GRU'?'selected':''}>${name} (${code})</option>`).join('')}</select></label><label>Destino da captura<select name="destination">${settings.destinations.map(d=>`<option value="${e(d.code)}">${e(d.city)} (${e(d.code)})</option>`).join('')}</select></label><label>Saída inicial<input type="date" name="departure_start" value="${addDays(1)}" required></label><label>Saída final<input type="date" name="departure_end" value="${addDays(30)}" required></label><label>Permanência mínima<input name="min_days" type="number" min="1" max="60" value="${settings.min_days}" required></label><label>Permanência máxima<input name="max_days" type="number" min="1" max="60" value="${settings.max_days}" required></label></div><div class="form-footer"><p>Pedidos novos entram na próxima rodada do motor, a cada 4 horas. Capturas completas recentes são reaproveitadas por até 4 horas.</p><button class="button primary" type="submit">${icon('calendar')} Solicitar captura</button></div></form><div id="calendar-results">${calendarJobsView()}</div></section>`;}
function calendarJobsView(){return calendarJobs.length?`<div class="table-scroll"><table><thead><tr><th>Rota</th><th>Status</th><th>Preços capturados</th><th>Pedido</th><th></th></tr></thead><tbody>${calendarJobs.map(j=>`<tr><td><b>${e(j.request.origin)} → ${e(j.request.destination)}</b><small class="block">${j.request.min_days}–${j.request.max_days} dias</small></td><td><span class="status-pill ${j.status==='completed'?'green':'neutral'}">${e({queued:'Na fila',running:'Capturando',completed:'Concluída',partial:'Parcial',failed:'Falhou'}[j.status]||j.status)}</span>${j.error?`<small class="block">${e(j.error)}</small>`:''}</td><td>${j.result?number(j.result.priced_combinations):'—'}</td><td>${new Date(j.created_at).toLocaleString('pt-BR')}</td><td>${j.result?`<button class="text-button" data-calendar-job="${e(j.id)}">Ver preços ${icon('arrow')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small-copy">As capturas automáticas e seus pedidos aparecerão aqui. Preços de calendário são referências; a consulta detalhada identifica a companhia antes da publicação de uma oferta.</p>';}
function bindCalendarJobs(){document.querySelectorAll('[data-calendar-job]').forEach(b=>b.onclick=()=>calendarResultModal(b.dataset.calendarJob));}
async function loadCalendarJobs(){try{calendarJobs=check(await db.from('calendar_jobs').select('id,status,request,result,error,created_at,expires_at').order('created_at',{ascending:false}).limit(8))||[];const target=document.querySelector('#calendar-results');if(target){target.innerHTML=calendarJobsView();bindCalendarJobs();}}catch(err){console.error('Não foi possível atualizar as capturas.');}}
async function calendarApi(body){const result=await db.functions.invoke('calendar-api',{body});if(result.error){let message='Não foi possível consultar a API de calendário.';try{message=(await result.error.context.json()).error||message;}catch{}throw new Error(message);}return result.data;}
async function queueCalendar(ev){ev.preventDefault();if(demo)return toast('A demonstração não executa capturas. Entre com sua conta administrativa.');const f=new FormData(ev.target);const request={origin:f.get('origin'),destination:f.get('destination'),departure_start:f.get('departure_start'),departure_end:f.get('departure_end'),min_days:+f.get('min_days'),max_days:+f.get('max_days'),max_stops:settings.max_stops};ev.submitter.disabled=true;try{const result=await calendarApi({action:'create',request});await loadCalendarJobs();toast(result.cached?'Captura recente encontrada no cache.':'Captura adicionada à próxima rodada do motor.');if(result.cached)await calendarResultModal(result.job_id);}catch(err){fail(err);}finally{ev.submitter.disabled=false;}}
async function calendarResultModal(id){try{const job=await calendarApi({action:'get',id});const r=job.result;if(!r)return toast('A captura ainda não terminou.');showModal(`<span class="eyebrow">CALENDÁRIO · ${e(job.request.origin)} → ${e(job.request.destination)}</span><h2>${number(r.priced_combinations)} preços capturados.</h2><p class="muted">${r.status==='partial'?'Captura parcial. ':''}${job.stale?'Dados anteriores ao período de atualização. ':''}As ${Math.min(30,r.entries.length)} menores tarifas aparecem abaixo. Companhia e preço final precisam de validação detalhada.</p><div class="table-scroll"><table><thead><tr><th>Ida</th><th>Volta</th><th>Dias</th><th>Preço</th></tr></thead><tbody>${r.entries.slice(0,30).map(v=>`<tr><td>${fmtDate(v.departure_date,true)}</td><td>${fmtDate(v.return_date,true)}</td><td>${v.stay_days}</td><td><b>${money(v.price_brl)}</b></td></tr>`).join('')}</tbody></table></div><p class="muted small-copy">${number(r.calendar_requests)} consultas de calendário · ${number(r.search_calls)} chamadas de pesquisa. ${e(r.note||'')}</p>`);}catch(err){fail(err);}}

function bindPage(){document.querySelector('#hero-radar')?.addEventListener('click',radarModal);document.querySelector('#new-radar')?.addEventListener('click',radarModal);document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;render();});document.querySelector('#origin-filter')?.addEventListener('change',ev=>{origin=ev.target.value;render();});document.querySelector('#sort')?.addEventListener('change',ev=>{sort=ev.target.value;render();});document.querySelector('#search')?.addEventListener('input',ev=>{search=ev.target.value;clearTimeout(timer);timer=setTimeout(()=>{const pos=ev.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);},220);});document.querySelector('#open-filters')?.addEventListener('click',filtersModal);document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.favorite));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detailModal(b.dataset.detail));document.querySelectorAll('[data-toggle-monitor]').forEach(b=>b.onclick=()=>toggleMonitor(b.dataset.toggleMonitor));document.querySelectorAll('[data-delete-monitor]').forEach(b=>b.onclick=()=>deleteMonitor(b.dataset.deleteMonitor));document.querySelector('#preferences-form')?.addEventListener('submit',savePreferences);document.querySelector('[data-go-radars]')?.addEventListener('click',()=>{page='radars';render();});document.querySelector('#pro-interest')?.addEventListener('click',proInterest);document.querySelector('#change-password')?.addEventListener('click',passwordModal);document.querySelector('#scanner-form')?.addEventListener('submit',saveScanner);document.querySelector('#add-destination')?.addEventListener('click',destinationModal);document.querySelector('#calendar-form')?.addEventListener('submit',queueCalendar);bindCalendarJobs();document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>memberModal(b.dataset.member));}
function showModal(content){modal.innerHTML=`<button class="modal-close icon-button" aria-label="Fechar">${icon('close')}</button>${content}`;modal.querySelector('.modal-close').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)modal.close();}});
async function toggleFavorite(id){try{if(busy)return;busy=true;const exists=favorites.includes(id);if(!demo){const result=exists?await db.from('favorites').delete().eq('user_id',profile.id).eq('offer_id',id):await db.from('favorites').insert({user_id:profile.id,offer_id:id});check(result);}favorites=exists?favorites.filter(f=>f!==id):[...favorites,id];if(demo)localStorage.setItem('orbita-demo-favorites',JSON.stringify(favorites));render();toast(exists?'Oportunidade removida das favoritas.':'Um novo destino guardado nas favoritas.');}catch(err){fail(err);}finally{busy=false;}}
function detailModal(id){const o=offers.find(o=>o.id===id);const latam=hasLatamProjection(o);const est=estimate(o.price_brl,prefs.cost_per_thousand,prefs.estimated_taxes);const fresh=new Date(o.expires_at)>new Date();showModal(`<span class="eyebrow">${e(o.origin)} → ${e(o.destination)} · ${e(airlineLabel(o))}</span><h2>${e(o.city)} está no seu radar.</h2><p class="muted">${fmtDate(o.departure_date,true)} a ${fmtDate(o.return_date,true)} · ${o.stay_days} dias</p><div class="detail-price"><span>Tarifa ${o.is_demo?'fictícia de demonstração':'encontrada'} · ida e volta</span><strong>${money(o.price_brl)}</strong></div>${latam?`<div class="detail-projection"><h3>${icon('sparkle')} Planejamento com milhas</h3><p>Para economizar 25–30%, o custo total do resgate precisaria ficar entre <b>${money(est.low)} e ${money(est.high)}</b>.</p><div class="simulation-row"><span>Exemplo de orçamento de milhas</span><b>${number(est.miles)} milhas</b></div><div class="simulation-row"><span>Custo por milheiro considerado</span><b>${money(est.costPerThousand)}</b></div><div class="simulation-row"><span>Taxas ilustrativas consideradas</span><b>${money(est.taxes)}</b></div><small>Este orçamento não é uma cotação de resgate. Não consultamos o saldo nem o inventário do LATAM Pass. As milhas acima são o máximo aproximado para atingir a meta intermediária com suas premissas.</small></div>`:''}<p class="muted small-copy">Companhia identificada nas opções de ida. Confirme a companhia da volta e todas as condições na seleção final.</p><div class="detail-source">${icon('clock')} ${o.is_demo?'Dados fictícios, sem consulta real':`Consultado em ${new Date(o.collected_at).toLocaleString('pt-BR')}`}${fresh?'':' · Tarifa desatualizada'}</div><div class="modal-actions"><a class="button primary" href="${e(safeFlightUrl(o.booking_url))}" target="_blank" rel="noopener noreferrer">${o.is_demo?'Pesquisar no Google Flights':'Conferir tarifa no Google'} ${icon('external')}</a>${latam?`<a class="button secondary" href="https://latampass.latam.com/pt_br/" target="_blank" rel="noopener noreferrer">Consultar LATAM Pass ${icon('external')}</a>`:''}</div>`);}
function safeFlightUrl(url){try{const u=new URL(url);if(u.protocol==='https:'&&['www.google.com','google.com'].includes(u.hostname))return u.href;}catch{}return'https://www.google.com/travel/flights?hl=pt-BR&curr=BRL';}
function filtersModal(){showModal(`<span class="eyebrow">MAIS PERTO DA SUA VIAGEM</span><h2>Refine suas oportunidades.</h2><form id="filters-form"><label>Tarifa máxima ida e volta (R$)<input name="price" type="number" min="1" value="${e(maxPrice)}" placeholder="Sem limite"></label><div class="form-grid"><label>Saída a partir de<input type="date" name="from" value="${e(departureFrom)}"></label><label>Saída até<input type="date" name="to" value="${e(departureTo)}"></label></div><div class="modal-actions"><button class="button primary" type="submit">Aplicar filtros ${icon('check')}</button><button class="button secondary" type="button" id="reset-filters">Limpar filtros</button></div></form>`);modal.querySelector('#filters-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);if(f.get('from')&&f.get('to')&&f.get('from')>f.get('to'))return toast('A data final deve ser posterior à inicial.');maxPrice=f.get('price');departureFrom=f.get('from');departureTo=f.get('to');modal.close();render();};modal.querySelector('#reset-filters').onclick=()=>{maxPrice='';departureFrom='';departureTo='';region='all';origin='all';search='';modal.close();render();};}
function radarModal(){if(monitors.length>=(isPro()?30:3)){toast('Você chegou ao limite de radares do seu plano.');return;}showModal(`<span class="eyebrow">DEIXE O RADAR ENCONTRAR</span><h2>Para onde vamos?</h2><p class="muted">Sua rota será incluída nas próximas pesquisas do motor.</p><form id="radar-form"><div class="form-grid"><label>Saindo de<select name="origin">${origins.map(([c,n])=>`<option value="${c}">${n} (${c})</option>`).join('')}</select></label><label>Chegando em<select name="destination">${settings.destinations.map(d=>`<option value="${e(d.code)}">${e(d.city)} (${e(d.code)})</option>`).join('')}</select></label><label>Permanência mínima (dias)<input name="min" type="number" min="1" max="60" value="${settings.min_days}" required></label><label>Permanência máxima (dias)<input name="max" type="number" min="1" max="60" value="${settings.max_days}" required></label></div><label>Tarifa desejada em reais (opcional)<input name="target" type="number" min="1" max="100000" placeholder="Ex.: 3500"></label><p class="muted small-copy">Classe econômica, 1 adulto, ida e volta. Saídas de amanhã até ${settings.horizon_months} meses à frente.</p><button type="submit" class="button primary wide">${icon('radar')} Criar radar</button></form>`);modal.querySelector('#radar-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);if(+f.get('min')>+f.get('max'))return toast('A permanência mínima deve ser menor que a máxima.');const m={origin:f.get('origin'),destination:f.get('destination'),min_days:+f.get('min'),max_days:+f.get('max'),target_price:f.get('target')?+f.get('target'):null,enabled:true};ev.submitter.disabled=true;try{if(demo){m.id=crypto.randomUUID();monitors.push(m);localStorage.setItem('orbita-demo-monitors',JSON.stringify(monitors));}else{const data=check(await db.from('monitors').insert({...m,user_id:profile.id}).select().single());monitors.push(data);}modal.close();page='radars';render();toast(demo?'Radar de demonstração salvo neste navegador.':'Radar criado. Ele entrará na próxima rodada de pesquisas.');}catch(err){fail(err);ev.submitter.disabled=false;}};}
async function toggleMonitor(id){const m=monitors.find(m=>m.id===id);try{if(!demo)check(await db.from('monitors').update({enabled:!m.enabled}).eq('id',id));m.enabled=!m.enabled;if(demo)localStorage.setItem('orbita-demo-monitors',JSON.stringify(monitors));render();}catch(err){fail(err);}}
async function deleteMonitor(id){showModal(`<h2>Excluir este radar?</h2><p class="muted">Você pode criar uma nova rota quando quiser.</p><button class="button primary" id="confirm-delete">Excluir radar</button>`);modal.querySelector('#confirm-delete').onclick=async()=>{try{if(!demo)check(await db.from('monitors').delete().eq('id',id));monitors=monitors.filter(m=>m.id!==id);if(demo)localStorage.setItem('orbita-demo-monitors',JSON.stringify(monitors));modal.close();render();toast('Radar excluído.');}catch(err){fail(err);}};}
async function savePreferences(ev){ev.preventDefault();const f=new FormData(ev.target),next={cost_per_thousand:+f.get('cost_per_thousand'),estimated_taxes:+f.get('estimated_taxes')};try{if(!demo)check(await db.from('preferences').upsert({...next,user_id:profile.id},{onConflict:'user_id'}));prefs=next;toast('Suas premissas foram atualizadas.');}catch(err){fail(err);}}
async function proInterest(){try{if(!demo)check(await db.from('pro_interest').upsert({user_id:profile.id},{onConflict:'user_id'}));toast(demo?'Demonstração: o interesse seria registrado na sua conta.':'Interesse registrado. Você acompanhará as novidades pela plataforma.');}catch(err){fail(err);}}
function passwordModal(){if(demo)return toast('Alteração de senha disponível nas contas reais.');showModal('<h2>Atualize sua senha.</h2><form id="password-form"><label>Nova senha<input type="password" name="password" autocomplete="new-password" minlength="10" required></label><button class="button primary" type="submit">Salvar senha</button></form>');modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{check(await db.auth.updateUser({password:new FormData(ev.target).get('password')}));modal.close();toast('Senha atualizada.');}catch(err){fail(err);}};}
async function saveScanner(ev){ev.preventDefault();const f=new FormData(ev.target);const next={...settings,enabled:f.has('enabled'),origins:f.getAll('origins'),destinations:settings.destinations.map(d=>({...d,enabled:f.getAll('destinations').includes(d.code)})),min_days:+f.get('min_days'),max_days:+f.get('max_days'),horizon_months:+f.get('horizon_months'),query_budget:+f.get('query_budget'),search_mode:f.get('search_mode'),search_strategy:f.get('search_strategy'),max_stops:+f.get('max_stops')};if(next.min_days>next.max_days||!next.origins.length||!next.destinations.some(d=>d.enabled))return toast('Escolha origens, destinos e um intervalo de permanência válido.');try{if(demo)localStorage.setItem('orbita-demo-settings',JSON.stringify(next));else{const {id,...patch}=next;delete patch.updated_at;check(await db.from('scanner_settings').update(patch).eq('id',1));}settings=next;toast(demo?'Configuração salva na demonstração. Nenhuma busca será executada.':'Configuração salva para a próxima rodada.');}catch(err){fail(err);}}
function destinationModal(){showModal('<h2>Adicione um novo destino.</h2><form id="destination-form"><div class="form-grid"><label>Aeroporto IATA<input name="code" pattern="[A-Za-z]{3}" maxlength="3" placeholder="SCL" required></label><label>Cidade<input name="city" maxlength="60" required placeholder="Santiago"></label><label>País<input name="country" maxlength="60" required placeholder="Chile"></label><label>Região<select name="region"><option>América do Sul</option><option>EUA</option><option>Europa</option><option>Ásia</option><option>Outros</option></select></label></div><button class="button primary" type="submit">Adicionar à configuração</button></form>');modal.querySelector('form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),code=f.get('code').toUpperCase();if(settings.destinations.some(d=>d.code===code))return toast('Este aeroporto já está na lista.');settings.destinations.push({code,city:f.get('city'),country:f.get('country'),region:f.get('region'),enabled:true});modal.close();render();toast('Destino adicionado. Salve a configuração para confirmar.');};}
function memberModal(id){const m=members.find(m=>m.id===id);showModal(`<h2>Gerenciar acesso</h2><p class="muted">${e(m.email)}</p><form id="member-form"><label>Plano<select name="plan"><option value="free" ${m.plan==='free'?'selected':''}>Free</option><option value="pro" ${m.plan==='pro'?'selected':''}>Pro · liberação administrativa</option></select></label><label>Acesso<select name="status"><option value="active" ${m.status==='active'?'selected':''}>Ativo</option><option value="suspended" ${m.status==='suspended'?'selected':''}>Suspenso</option></select></label><label>Pro válido até (opcional)<input type="datetime-local" name="until"></label><button class="button primary" type="submit">Salvar acesso</button></form>`);modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);try{check(await db.rpc('admin_update_member',{target_id:id,new_plan:f.get('plan'),new_status:f.get('status'),valid_until:f.get('until')?new Date(f.get('until')).toISOString():null}));modal.close();await loadLive();toast('Acesso atualizado.');}catch(err){fail(err);}};}
function legalView(){showModal(`<span class="eyebrow">TRANSPARÊNCIA</span><h2>Termos e privacidade</h2><div class="legal-copy"><h3>Uso da plataforma</h3><p>O Órbita organiza referências de tarifas aéreas e simulações de custo com milhas. Não vende passagens, não emite bilhetes e não garante tarifas, disponibilidade ou economia. Confirme todas as condições com o fornecedor antes de comprar ou resgatar.</p><h3>Dados da sua conta</h3><p>Guardamos nome, e-mail, registro de aceite, preferências, favoritos e rotas monitoradas no Supabase. A autenticação é gerenciada pelo Supabase Auth. Não solicitamos credenciais nem saldo da sua conta LATAM Pass.</p><h3>Dados e serviços externos</h3><p>As pesquisas de tarifas são executadas pelo motor no GitHub Actions e consultam o Google Flights por uma biblioteca não oficial. O portal utiliza armazenamento local para manter sua sessão e preferências de demonstração. Links externos seguem as políticas dos respectivos serviços.</p><h3>Seus direitos</h3><p>Você pode solicitar acesso, correção e exclusão dos seus dados ao responsável pela plataforma. Antes da abertura comercial, o operador deverá publicar sua identificação, contato de privacidade, política de retenção e termos comerciais definitivos.</p><h3>Planos</h3><p>O plano Pro está em preparação. Registrar interesse não gera assinatura ou cobrança.</p></div>`);}
async function start(){
 if(demo)return loadDemo();
 if(!db)return authView();
 let ready=false,recovery=false;
 db.auth.onAuthStateChange((event,s)=>{
  session=s;
  if(event==='PASSWORD_RECOVERY'){recovery=true;authMode='recovery';authView();}
  else if(ready&&event==='SIGNED_OUT'&&!demo){profile=null;authView();}
  else if(ready&&event==='SIGNED_IN'&&!profile&&!demo){setTimeout(loadLive,0);}
 });
 const {data,error}=await db.auth.getSession();
 ready=true;
 if(error){authView();return fail(error);}
 session=data.session;
 if(recovery)return;
 if(session)await loadLive();else authView();
 setInterval(()=>{
  const editing=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName);
  if(!demo&&session&&profile&&page==='admin'&&!modal.open&&!busy)loadCalendarJobs();
  if(!demo&&session&&profile&&['discover','saved','activity'].includes(page)&&!modal.open&&!editing&&!busy&&document.visibilityState==='visible')loadLive();
 },60000);
}
start().catch(err=>{authView();fail(err);});
